<?php
declare(strict_types=1);
return static function (PDO $pdo): void {
    $sqlite=class_exists('EnterpriseSqlitePdo',false) && $pdo instanceof EnterpriseSqlitePdo;
    if($sqlite){
        $pdo->exec("CREATE TABLE IF NOT EXISTS dataforms (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,description TEXT NULL,status TEXT NOT NULL DEFAULT 'draft',df_uuid TEXT NULL UNIQUE,license_status TEXT NOT NULL DEFAULT 'unlicensed',license_registered_at INTEGER NULL,license_token TEXT NULL,license_token_key_id TEXT NULL,license_token_issued_at INTEGER NULL,table_save_mode TEXT NOT NULL DEFAULT 'manual',show_save_success INTEGER NOT NULL DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP)");
        $pdo->exec("CREATE TABLE IF NOT EXISTS dataform_fields (id INTEGER PRIMARY KEY AUTOINCREMENT,dataform_id INTEGER NOT NULL,name TEXT NOT NULL,label TEXT NOT NULL,field_type TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,is_required INTEGER NOT NULL DEFAULT 0,configuration_json TEXT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(dataform_id) REFERENCES dataforms(id) ON DELETE CASCADE,UNIQUE(dataform_id,name))"); return;
    }
    $pdo->exec("CREATE TABLE IF NOT EXISTS dataforms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, slug VARCHAR(160) NOT NULL UNIQUE, description TEXT NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', df_uuid VARCHAR(36) NULL UNIQUE, license_status VARCHAR(24) NOT NULL DEFAULT 'unlicensed', license_registered_at BIGINT NULL, license_token LONGTEXT NULL, license_token_key_id VARCHAR(100) NULL, license_token_issued_at BIGINT NULL, table_save_mode VARCHAR(20) NOT NULL DEFAULT 'manual', show_save_success TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS dataform_fields (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, dataform_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL, label VARCHAR(190) NOT NULL, field_type VARCHAR(80) NOT NULL, position INT NOT NULL DEFAULT 0, is_required TINYINT(1) NOT NULL DEFAULT 0, configuration_json LONGTEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_field_form FOREIGN KEY(dataform_id) REFERENCES dataforms(id) ON DELETE CASCADE, UNIQUE KEY uq_form_field(dataform_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
};
